14	// NUMERIC SORTS
15	// ``reverse=true`` performs a descending sort using the same comparator,
16	// preserving NaN-at-end semantics for floating-point inputs.
17	template <bool reverse = false, typename T>
18	inline void Quick(T *start, SSize num)
19	{
20	    T vp;
21	    T *pl = start;
22	    T *pr = pl + num - 1;
23	    T *stack[kQuickStack];
24	    T **sptr = stack;
25	    T *pm, *pi, *pj, *pk;
26	    int depth[kQuickStack];
27	    int *psdepth = depth;
28	    int cdepth = BitScanReverse(static_cast<std::make_unsigned_t<SSize>>(num)) * 2;
29	    for (;;) {
30	        if (NPY_UNLIKELY(cdepth < 0)) {
31	            Heap<reverse>(pl, pr - pl + 1);
32	            goto stack_pop;
33	        }
34	        while ((pr - pl) > kQuickSmall) {
35	            // quicksort partition
36	            pm = pl + ((pr - pl) >> 1);
37	            if (Cmp<reverse>(*pm, *pl)) {
38	                std::swap(*pm, *pl);
39	            }
40	            if (Cmp<reverse>(*pr, *pm)) {
41	                std::swap(*pr, *pm);
42	            }
43	            if (Cmp<reverse>(*pm, *pl)) {
44	                std::swap(*pm, *pl);
45	            }
46	            vp = *pm;
47	            pi = pl;
48	            pj = pr - 1;
49	            std::swap(*pm, *pj);
50	            for (;;) {
51	                do {
52	                    ++pi;
53	                } while (Cmp<reverse>(*pi, vp));
54	                do {
55	                    --pj;
56	                } while (Cmp<reverse>(vp, *pj));
57	                if (pi >= pj) {
58	                    break;
59	                }
60	                std::swap(*pi, *pj);
61	            }
62	            pk = pr - 1;
63	            std::swap(*pi, *pk);
64	            // push largest partition on stack
65	            if (pi - pl < pr - pi) {
66	                *sptr++ = pi + 1;
67	                *sptr++ = pr;
68	                pr = pi - 1;
69	            }
70	            else {
71	                *sptr++ = pl;
72	                *sptr++ = pi - 1;
73	                pl = pi + 1;
74	            }
75	            *psdepth++ = --cdepth;
76	        }
77	
78	        /* insertion sort */
79	        for (pi = pl + 1; pi <= pr; ++pi) {
80	            vp = *pi;
81	            pj = pi;
82	            pk = pi - 1;
83	            while (pj > pl && Cmp<reverse>(vp, *pk)) {
84	                *pj-- = *pk--;
85	            }
86	            *pj = vp;
87	        }
88	    stack_pop:
89	        if (sptr == stack) {
