#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include "x86simdsort-static-incl.h"

using namespace std;

template <typename T>
void run(int n, const T *arr) {
    vector<size_t> arg(n);
    for (int i = 0; i < n; i++) arg[i] = (size_t)i;
    x86simdsortStatic::argsort(arr, arg.data(), (size_t)n, true);
    for (int i = 0; i < n; i++) {
        if (i) printf(" ");
        printf("%zu", arg[i]);
    }
    printf("\n");
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    string t = argv[1];
    int n = atoi(argv[2]);
    if (t == "int64" || t == "int32" || t == "float64" || t == "float32") {
        if (t == "int64") {
            vector<int64_t> v(n);
            for (int i = 0; i < n; i++) { long long x; scanf("%lld", &x); v[i] = x; }
            run(n, v.data());
        } else if (t == "int32") {
            vector<int32_t> v(n);
            for (int i = 0; i < n; i++) { int x; scanf("%d", &x); v[i] = x; }
            run(n, v.data());
        } else if (t == "float64") {
            vector<double> v(n);
            for (int i = 0; i < n; i++) { scanf("%lf", &v[i]); }
            run(n, v.data());
        } else {
            vector<float> v(n);
            for (int i = 0; i < n; i++) { scanf("%f", &v[i]); }
            run(n, v.data());
        }
    }
    return 0;
}

