float_ops!(f32);

fn msb(n: usize) -> i32 {
    (usize::BITS - 1 - n.leading_zeros()) as i32
}

// ---------- numpy's own introsort argsort (aquicksort_ + aheapsort_) ----------

fn intro_heap<K: Kops>(v: &[K::K], out: &mut [usize], n: usize) {
    // npy_aheapsort: 1-based heap over out[0..n] (a[i] == out[i-1])
    let mut l = n >> 1;
    while l > 0 {
        let tmp = out[l - 1];
        let mut i = l;
        let mut j = l << 1;
        while j <= n {
            if j < n && K::intro_lt(v[out[j - 1]], v[out[j]]) {
                j += 1;
            }
            if K::intro_lt(v[tmp], v[out[j - 1]]) {
                out[i - 1] = out[j - 1];
                i = j;
                j += j;
            } else {
                break;
            }
        }
        out[i - 1] = tmp;
        l -= 1;
    }
    let mut m = n;
    while m > 1 {
        let tmp = out[m - 1];
        out[m - 1] = out[0];
        m -= 1;
        let mut i = 1;
        let mut j = 2;
        while j <= m {
            if j < m && K::intro_lt(v[out[j - 1]], v[out[j]]) {
                j += 1;
            }
            if K::intro_lt(v[tmp], v[out[j - 1]]) {
                out[i - 1] = out[j - 1];
                i = j;
                j += j;
            } else {
                break;
            }
        }
        out[i - 1] = tmp;
    }
}

fn intro_argsort<K: Kops>(v: &[K::K], out: &mut [usize]) {
    let n = v.len();
    if n <= 1 {
        return;
    }
    let mut stack: Vec<(usize, usize, i32)> = Vec::new();
    let mut pl = 0usize;
    let mut pr = n - 1;
    let mut cdepth = msb(n) * 2;
    loop {
        if cdepth < 0 {
            intro_heap::<K>(v, &mut out[pl..=pr], pr - pl + 1);
            if let Some((l, r, d)) = stack.pop() {
                pl = l;
                pr = r;
                cdepth = d;
            } else {
                return;
            }
            continue;
        }
        while pr - pl > 15 {
            let pm = pl + ((pr - pl) >> 1);
            if K::intro_lt(v[out[pm]], v[out[pl]]) {
                out.swap(pm, pl);
            }
            if K::intro_lt(v[out[pr]], v[out[pm]]) {
                out.swap(pr, pm);
            }
            if K::intro_lt(v[out[pm]], v[out[pl]]) {
                out.swap(pm, pl);
            }
            let vp = v[out[pm]];
            let mut pi = pl;
            let mut pj = pr - 1;
            out.swap(pm, pj);
            loop {
                pi += 1;
                while K::intro_lt(v[out[pi]], vp) {
                    pi += 1;
                }
                pj -= 1;
                while K::intro_lt(vp, v[out[pj]]) {
                    pj -= 1;
                }
                if pi >= pj {
                    break;
                }
                out.swap(pi, pj);
            }
            out.swap(pi, pr - 1);
            if pi - pl < pr - pi {
                stack.push((pi + 1, pr, cdepth - 1));
                pr = pi - 1;
            } else {
                stack.push((pl, pi - 1, cdepth - 1));
                pl = pi + 1;
            }
            cdepth -= 1;
        }
        for pi in (pl + 1)..=pr {
            let vi = out[pi];
            let vp = v[vi];
            let mut pj = pi;
            while pj > pl && K::intro_lt(vp, v[out[pj - 1]]) {
                out[pj] = out[pj - 1];
                pj -= 1;
            }
            out[pj] = vi;
        }
        if let Some((l, r, d)) = stack.pop() {
            pl = l;
            pr = r;
            cdepth = d;
        } else {
            return;
        }
    }
}

// ---------- x86-simd-sort argsort, emulated lane by lane ----------

fn mask_bits<const L: usize>(bits: u64) -> [bool; L] {
    let mut m = [false; L];
    for l in 0..L {
        m[l] = (bits >> l) & 1 == 1;
    }
    m
}

// swap neighbouring halves inside each block of SCALE lanes
fn swap_n<const SCALE: usize, const L: usize, K: Kops>(x: &mut [K::K; L]) {
    let mut base = 0;
    while base < L {
        for j in 0..SCALE / 2 {
            x.swap(base + j, base + SCALE / 2 + j);
        }
        base += SCALE;
    }
}
// reverse inside each block of SCALE lanes
fn reverse_n<const SCALE: usize, const L: usize, K: Kops>(x: &mut [K::K; L]) {
    let mut base = 0;
    while base < L {
        let (mut lo, mut hi) = (base, base + SCALE - 1);
        while lo < hi {
            x.swap(lo, hi);
            lo += 1;
            hi -= 1;
        }
        base += SCALE;
    }
}
fn swap_n_u<const SCALE: usize, const L: usize>(x: &mut [usize; L]) {
    let mut base = 0;
    while base < L {
        for j in 0..SCALE / 2 {
            x.swap(base + j, base + SCALE / 2 + j);
        }
        base += SCALE;
    }
}
fn reverse_n_u<const SCALE: usize, const L: usize>(x: &mut [usize; L]) {
    let mut base = 0;
    while base < L {
        let (mut lo, mut hi) = (base, base + SCALE - 1);
        while lo < hi {
            x.swap(lo, hi);
            lo += 1;
            hi -= 1;
        }
        base += SCALE;
    }
}

// xss-common-qsort.h cmp_merge: mask lanes take max(in2,in1), the rest min(in2,in1)
fn cmp_merge_single<const L: usize, K: Kops>(in1: &[K::K; L], in2: &[K::K; L], mask: &[bool; L]) -> [K::K; L] {
    let mut out = [K::type_max(); L];
    for l in 0..L {
        let mn = K::min2(in2[l], in1[l]);
        let mx = K::max2(in2[l], in1[l]);
        out[l] = if mask[l] { mx } else { mn };
    }
    out
}

// key/index cmp_merge: when the chosen key came from in1 keep index1, else index2
fn cmp_merge_pair<const L: usize, K: Kops>(
    key_in1: &[K::K; L],
    key_in2: &[K::K; L],
    idx_in1: &[usize; L],
    idx_in2: &[usize; L],
    mask: &[bool; L],
) -> ([K::K; L], [usize; L]) {
    let keys = cmp_merge_single::<L, K>(key_in1, key_in2, mask);
    let mut idx = [0usize; L];
    for l in 0..L {
        idx[l] = if keys[l] == key_in1[l] { idx_in1[l] } else { idx_in2[l] };
    }
    (keys, idx)
}

fn sort_reg_4_pair<K: Kops>(key: &mut [K::K; 4], idx: &mut [usize; 4]) {
    let m_a = mask_bits::<4>(0xA);
    let m_c = mask_bits::<4>(0xC);
    let apply = |key: &mut [K::K; 4], idx: &mut [usize; 4], f: fn(&mut [usize; 4]), mask: &[bool; 4]| {
        let mut k2 = *key;
        let mut i2 = *idx;
        K::reverse_n4(&mut k2);
        f(&mut i2);
        let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, mask);
        *key = nk;
        *idx = ni;
    };
    let _ = apply;
    // reverse_n<2>
    let mut k2 = *key;
    let mut i2 = *idx;
    reverse_n::<2, 4, K>(&mut k2);
    reverse_n_u::<2, 4>(&mut i2);
    let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, &m_a);
    *key = nk;
    *idx = ni;
    // reverse_n<4>
    let mut k2 = *key;
    let mut i2 = *idx;
    reverse_n::<4, 4, K>(&mut k2);
    reverse_n_u::<4, 4>(&mut i2);
    let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, &m_c);
    *key = nk;
    *idx = ni;
    // swap_n<2>
    let mut k2 = *key;
    let mut i2 = *idx;
    swap_n::<2, 4, K>(&mut k2);
    swap_n_u::<2, 4>(&mut i2);
    let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, &m_a);
    *key = nk;
    *idx = ni;
}
impl Kops for [(); 0] {
    type K = ();
    fn lt(_a: (), _b: ()) -> bool {
        false
    }
    fn intro_lt(_a: (), _b: ()) -> bool {
        false
    }
    fn min2(_a: (), _b: ()) -> () {}
    fn max2(_a: (), _b: ()) -> () {}
    fn type_max() -> () {}
    fn type_min() -> () {}
}
trait Krev {
    fn reverse_n4<K: Kops>(_x: &mut [K::K; 4]);
}

fn sort_reg_8_pair<K: Kops>(key: &mut [K::K; 8], idx: &mut [usize; 8]) {
    let m_aa = mask_bits::<8>(0xAA);
    let m_cc = mask_bits::<8>(0xCC);
    let m_f0 = mask_bits::<8>(0xF0);
    macro_rules! step {
        ($kf:expr, $if:expr, $mask:expr) => {{
            let mut k2 = *key;
            let mut i2 = *idx;
            $kf(&mut k2);
            $if(&mut i2);
            let (nk, ni) = cmp_merge_pair::<8, K>(key, &k2, idx, &i2, $mask);
            *key = nk;
            *idx = ni;
        }};
    }
    step!(reverse_n::<2, 8, K>, reverse_n_u::<2, 8>, &m_aa);
    step!(reverse_n::<4, 8, K>, reverse_n_u::<4, 8>, &m_cc);
    step!(swap_n::<2, 8, K>, swap_n_u::<2, 8>, &m_aa);
    step!(reverse_n::<8, 8, K>, reverse_n_u::<8, 8>, &m_f0);
    step!(swap_n::<4, 8, K>, swap_n_u::<4, 8>, &m_cc);
    step!(swap_n::<2, 8, K>, swap_n_u::<2, 8>, &m_aa);
}

// single-register value sort (used for the pivot's median), no indices
fn sort_reg_4<K: Kops>(key: &mut [K::K; 4]) {
    let mut k2;
    k2 = *key;
    reverse_n::<2, 4, K>(&mut k2);
    *key = cmp_merge_single::<4, K>(key, &k2, &mask_bits::<4>(0xA));
    k2 = *key;
    reverse_n::<4, 4, K>(&mut k2);
    *key = cmp_merge_single::<4, K>(key, &k2, &mask_bits::<4>(0xC));
    k2 = *key;
    swap_n::<2, 4, K>(&mut k2);
    *key = cmp_merge_single::<4, K>(key, &k2, &mask_bits::<4>(0xA));
}
fn sort_reg_8<K: Kops>(key: &mut [K::K; 8]) {
    let m_aa = mask_bits::<8>(0xAA);
    let m_cc = mask_bits::<8>(0xCC);
    let m_f0 = mask_bits::<8>(0xF0);
    macro_rules! step {
        ($f:expr, $mask:expr) => {{
            let mut k2 = *key;
            $f(&mut k2);
            *key = cmp_merge_single::<8, K>(key, &k2, $mask);
        }};
    }
    step!(reverse_n::<2, 8, K>, &m_aa);
    step!(reverse_n::<4, 8, K>, &m_cc);
    step!(swap_n::<2, 8, K>, &m_aa);
    step!(reverse_n::<8, 8, K>, &m_f0);
    step!(swap_n::<4, 8, K>, &m_cc);
    step!(swap_n::<2, 8, K>, &m_aa);
}

fn bitonic_merge_reg_4<K: Kops>(key: &mut [K::K; 4], idx: &mut [usize; 4]) {
    let m_a = mask_bits::<4>(0xA);
    let m_c = mask_bits::<4>(0xC);
    let mut k2 = *key;
    let mut i2 = *idx;
    swap_n::<4, 4, K>(&mut k2);
    swap_n_u::<4, 4>(&mut i2);
    let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, &m_c);
    *key = nk;
    *idx = ni;
    let mut k2 = *key;
    let mut i2 = *idx;
    swap_n::<2, 4, K>(&mut k2);
    swap_n_u::<2, 4>(&mut i2);
    let (nk, ni) = cmp_merge_pair::<4, K>(key, &k2, idx, &i2, &m_a);
    *key = nk;
    *idx = ni;
}
fn bitonic_merge_reg_8<K: Kops>(key: &mut [K::K; 8], idx: &mut [usize; 8]) {
    let m_aa = mask_bits::<8>(0xAA);
    let m_cc = mask_bits::<8>(0xCC);
    let m_f0 = mask_bits::<8>(0xF0);
    macro_rules! step {
        ($kf:expr, $if:expr, $mask:expr) => {{
            let mut k2 = *key;
            let mut i2 = *idx;
            $kf(&mut k2);
            $if(&mut i2);
            let (nk, ni) = cmp_merge_pair::<8, K>(key, &k2, idx, &i2, $mask);
            *key = nk;
            *idx = ni;
        }};
    }
    step!(swap_n::<8, 8, K>, swap_n_u::<8, 8>, &m_f0);
    step!(swap_n::<4, 8, K>, swap_n_u::<4, 8>, &m_cc);
    step!(swap_n::<2, 8, K>, swap_n_u::<2, 8>, &m_aa);
}

fn coex_pair<const L: usize, K: Kops>(k1: &mut [K::K; L], k2: &mut [K::K; L], i1: &mut [usize; L], i2: &mut [usize; L]) {
    let k1_orig = *k1;
    let mut nk1 = [K::type_max(); L];
    let mut nk2 = [K::type_max(); L];
    for l in 0..L {
        nk1[l] = K::min2(k1[l], k2[l]);
        nk2[l] = K::max2(k1_orig[l], k2[l]);
        let eq = nk1[l] == k1_orig[l];
        let a = i1[l];
        let b = i2[l];
        i1[l] = if eq { a } else { b };
        i2[l] = if eq { b } else { a };
    }
    *k1 = nk1;
    *k2 = nk2;
}

fn coex_at<const L: usize, K: Kops>(keys: &mut [[K::K; L]], idxs: &mut [[usize; L]], a: usize, b: usize) {
    let (lo, hi) = keys.split_at_mut(b);
    let (loi, hii) = idxs.split_at_mut(b);
    coex_pair::<L, K>(&mut lo[a], &mut hi[0], &mut loi[a], &mut hii[0]);
}

fn bitonic_merge_n<const L: usize, K: Kops>(keys: &mut [[K::K; L]], idxs: &mut [[usize; L]]) {
    let numper = keys.len();
    if numper == 2 {
        keys[1].reverse();
        idxs[1].reverse();
        coex_pair::<L, K>(&mut keys[0], &mut keys[1], &mut idxs[0], &mut idxs[1]);
        keys[1].reverse();
        idxs[1].reverse();
    } else {
        for i in 0..numper / 2 {
            let j = numper - 1 - i;
            keys[j].reverse();
            idxs[j].reverse();
            coex_at::<L, K>(keys, idxs, i, j);
            keys[j].reverse();
            idxs[j].reverse();
        }
    }
    let mut num = numper / 2;
    while num >= 2 {
        let mut j = 0;
        while j < numper {
            for i in 0..num / 2 {
                coex_at::<L, K>(keys, idxs, j + i, j + i + num / 2);
            }
            j += num;
        }
        num /= 2;
    }
    for i in 0..numper {
        if L == 8 {
            bitonic_merge_reg_8::<K>(&mut keys[i], &mut idxs[i]);
        } else {
            bitonic_merge_reg_4::<K>(&mut keys[i], &mut idxs[i]);
        }
    }
}

fn bitonic_fullmerge<const L: usize, K: Kops>(keys: &mut Vec<[K::K; L]>, idxs: &mut Vec<[usize; L]>) {
    let nv = keys.len();
    let mut numper = 2;
    while numper <= nv {
        let mut start = 0;
        while start < nv {
            let (a, b) = (start, start + numper);
            let (kl, kr) = keys.split_at_mut(b);
            let (il, ir) = idxs.split_at_mut(b);
            bitonic_merge_n::<L, K>(&mut kl[a..], &mut il[a..]);
            let _ = kr;
            let _ = ir;
            start += numper;
        }
        numper *= 2;
    }
}

// sort N <= maxN elements with the fixed-size bitonic network of NV = maxN / L vectors
fn argsort_n_vec<const L: usize, const AVX512: bool, const NV: usize, K: Kops>(v: &[K::K], ind: &mut [usize], n: usize) {
    if NV > 1 && n * 2 <= NV * L {
        argsort_n_vec::<L, AVX512, { NV / 2 }, K>(v, ind, n);
        return;
    }
    let mut keys = vec![[K::type_max(); L]; NV];
    let mut idxs = vec![[usize::MAX; L]; NV];
    for i in 0..NV {
        let mask: [bool; L] = if i < NV / 2 {
            [true; L]
        } else {
            let num = n.saturating_sub(i * L).min(L);
            let mut m = [false; L];
            for l in 0..num {
                m[l] = true;
            }
            m
        };
        for l in 0..L {
            if mask[l] {
                idxs[i][l] = ind[i * L + l];
                keys[i][l] = v[idxs[i][l]];
            }
        }
        if L == 8 {
            sort_reg_8_pair::<K>(&mut keys[i], &mut idxs[i]);
        } else {
            sort_reg_4_pair::<K>(&mut keys[i], &mut idxs[i]);
        }
    }
    bitonic_fullmerge::<L, K>(&mut keys, &mut idxs);
    for i in 0..NV {
        let mask: [bool; L] = if i < NV / 2 {
            [true; L]
        } else {
            let num = n.saturating_sub(i * L).min(L);
            let mut m = [false; L];
            for l in 0..num {
                m[l] = true;
            }
            m
        };
        for l in 0..L {
            if mask[l] {
                ind[i * L + l] = idxs[i][l];
            }
        }
    }
}

fn get_pivot<const L: usize, K: Kops>(v: &[K::K], out: &[usize], left: usize, right: usize) -> K::K {
    if right - left >= L {
        let size = (right - left) / L;
        let mut r = [K::type_max(); L];
        for l in 0..L {
            r[l] = v[out[left + size * (l + 1)]];
        }
        if L == 8 {
            sort_reg_8::<K>(&mut r);
        } else {
            sort_reg_4::<K>(&mut r);
        }
        r[L / 2]
    } else {
        v[out[right]]
    }
}

fn partition_vec<const L: usize, const AVX512: bool, K: Kops>(
    v: &[K::K],
    out: &mut [usize],
    left: usize,
    right: usize, // exclusive end of the unpartitioned region
    arg_vec: &[usize; L],
    pivot: K::K,
) -> (usize, K::K, K::K) {
    let mut keys = [K::type_max(); L];
    let mut ge = [false; L];
    for l in 0..L {
        keys[l] = v[arg_vec[l]];
        ge[l] = !K::lt(keys[l], pivot);
    }
    let amount = ge.iter().filter(|x| **x).count();
    let minv = keys.iter().copied().fold(K::type_max(), K::min2);
    let maxv = keys.iter().copied().fold(K::type_min(), K::max2);
    if AVX512 {
        let mut p = left;
        for l in 0..L {
            if !ge[l] {
                out[p] = arg_vec[l];
                p += 1;
            }
        }
        let mut p = right - amount;
        for l in 0..L {
            if ge[l] {
                out[p] = arg_vec[l];
                p += 1;
            }
        }
    } else {
        // avx2_double_compressstore: write the same permuted register to both edges
        let mut perm = [0usize; L];
        let mut p = 0;
        for l in 0..L {
            if !ge[l] {
                perm[p] = arg_vec[l];
                p += 1;
            }
        }
        for l in 0..L {
            if ge[l] {
                perm[p] = arg_vec[l];
                p += 1;
            }
        }
        for l in 0..L {
            out[left + l] = perm[l];
            out[right - L + l] = perm[l];
        }
    }
    (amount, minv, maxv)
}

fn argpartition_unrolled<const L: usize, const AVX512: bool, K: Kops>(
    v: &[K::K],
    out: &mut [usize],
    mut left: usize,
    mut right: usize, // exclusive
    pivot: K::K,
    smallest: &mut K::K,
    biggest: &mut K::K,
) -> usize {
    for _ in 0..(right - left) % (4 * L) {
        let val = v[out[left]];
        *smallest = K::min2(*smallest, val);
        *biggest = K::max2(*biggest, val);
        if !K::lt(val, pivot) {
            out.swap(left, right - 1);
            right -= 1;
        } else {
            left += 1;
        }
    }
    if left == right {
        return left;
    }
    let mut vec_left: [[usize; L]; 4] = [[0; L]; 4];
    let mut vec_right: [[usize; L]; 4] = [[0; L]; 4];
    for ii in 0..4 {
        for l in 0..L {
            vec_left[ii][l] = out[left + L * ii + l];
            vec_right[ii][l] = out[right - L * (4 - ii) + l];
        }
    }
    let mut r_store = right - L;
    let mut l_store = left;
    left += 4 * L;
    right -= 4 * L;
    let mut minv = *smallest;
    let mut maxv = *biggest;
    while right - left != 0 {
        let mut curr: [[usize; L]; 4] = [[0; L]; 4];
        if (r_store + L) - right < left - l_store {
            right -= 4 * L;
            for ii in 0..4 {
                for l in 0..L {
                    curr[ii][l] = out[right + L * ii + l];
                }
            }
        } else {
            for ii in 0..4 {
                for l in 0..L {
                    curr[ii][l] = out[left + L * ii + l];
                }
            }
            left += 4 * L;
        }
        for ii in 0..4 {
            let (amt, mn, mx) = partition_vec::<L, AVX512, K>(v, out, l_store, r_store + L, &curr[ii], pivot);
            l_store += L - amt;
            r_store -= amt;
            minv = K::min2(minv, mn);
            maxv = K::max2(maxv, mx);
        }
    }
    for ii in 0..4 {
        let (amt, mn, mx) = partition_vec::<L, AVX512, K>(v, out, l_store, r_store + L, &vec_left[ii], pivot);
        l_store += L - amt;
        r_store -= amt;
        minv = K::min2(minv, mn);
        maxv = K::max2(maxv, mx);
    }
    for ii in 0..4 {
        let (amt, mn, mx) = partition_vec::<L, AVX512, K>(v, out, l_store, r_store + L, &vec_right[ii], pivot);
        l_store += L - amt;
        r_store -= amt;
        minv = K::min2(minv, mn);
        maxv = K::max2(maxv, mx);
    }
    *smallest = minv;
    *biggest = maxv;
    l_store
}

// Returns false when numpy would hand the segment to std::sort (only when the recursion
// exhausts its budget); the caller refuses rather than guess that order.
fn argsort_<const L: usize, const AVX512: bool, K: Kops>(
    v: &[K::K],
    out: &mut [usize],
    left: usize,
    right: usize,
    max_iters: usize,
) -> bool {
    if max_iters == 0 {
        return false;
    }
    let len = right + 1 - left;
    if len <= 256 {
        argsort_n_vec::<L, AVX512, { 256 / L }, K>(v, &mut out[left..right + 1], len);
        return true;
    }
    let pivot = get_pivot::<L, K>(v, out, left, right);
    let mut smallest = K::type_max();
    let mut biggest = K::type_min();
    let pi = argpartition_unrolled::<L, AVX512, K>(v, out, left, right + 1, pivot, &mut smallest, &mut biggest);
    if pivot != smallest && !argsort_::<L, AVX512, K>(v, out, left, pi - 1, max_iters - 1) {
        return false;
    }
    if pivot != biggest && !argsort_::<L, AVX512, K>(v, out, pi, right, max_iters - 1) {
        return false;
    }
    true
}

fn xss_argsort<const L: usize, const AVX512: bool, K: Kops>(v: &[K::K], out: &mut [usize]) -> bool {
    let n = v.len();
    if n <= 1 {
        return true;
    }
    // numpy leaves an already non-decreasing array untouched (identity indices)
    if !v.windows(2).any(|w| K::lt(w[1], w[0])) {
        return true;
    }
    let max_iters = (2.0 * (n as f64).log2()) as usize;
    argsort_::<L, AVX512, K>(v, out, 0, n - 1, max_iters)
}

// ---------- numpy's dispatch: X86_V4 first, then X86_V3, else introsort ----------

#[derive(Clone, Copy, PartialEq)]
enum NpPath {
    Intro,
    Avx2,
    Avx512,
}

#[cfg(target_arch = "x86_64")]
fn x86_v2() -> bool {
    use std::arch::x86_64::__cpuid;
    let l1 = unsafe { __cpuid(1) };
    let cx16 = l1.ecx & (1 << 13) != 0;
    let ext = unsafe { __cpuid(0x8000_0001) };
    let lahf = ext.ecx & 1 != 0;
    std::arch::is_x86_feature_detected!("sse")
        && std::arch::is_x86_feature_detected!("sse2")
        && std::arch::is_x86_feature_detected!("sse3")
        && std::arch::is_x86_feature_detected!("ssse3")
        && std::arch::is_x86_feature_detected!("sse4.1")
        && std::arch::is_x86_feature_detected!("sse4.2")
        && std::arch::is_x86_feature_detected!("popcnt")
        && lahf
        && cx16
}
#[cfg(target_arch = "x86_64")]
fn x86_v3() -> bool {
    x86_v2()
        && std::arch::is_x86_feature_detected!("avx")
        && std::arch::is_x86_feature_detected!("avx2")
        && std::arch::is_x86_feature_detected!("fma")
        && std::arch::is_x86_feature_detected!("bmi1")
        && std::arch::is_x86_feature_detected!("bmi2")
        && std::arch::is_x86_feature_detected!("lzcnt")
        && std::arch::is_x86_feature_detected!("f16c")
        && std::arch::is_x86_feature_detected!("movbe")
}
#[cfg(target_arch = "x86_64")]
fn x86_v4() -> bool {
    x86_v3()
        && std::arch::is_x86_feature_detected!("avx512f")
        && std::arch::is_x86_feature_detected!("avx512cd")
        && std::arch::is_x86_feature_detected!("avx512bw")
        && std::arch::is_x86_feature_detected!("avx512dq")
        && std::arch::is_x86_feature_detected!("avx512vl")
}
#[cfg(not(target_arch = "x86_64"))]
fn x86_v2() -> bool {
    false
}
#[cfg(not(target_arch = "x86_64"))]
fn x86_v3() -> bool {
    false
}
#[cfg(not(target_arch = "x86_64"))]
fn x86_v4() -> bool {
    false
}

fn np_path() -> NpPath {
    if x86_v4() {
        NpPath::Avx512
    } else if x86_v3() {
        NpPath::Avx2
    } else {
        NpPath::Intro
    }
}

// Fill out with numpy's default-kind argsort of v. false = this path is not reproduced
// (the caller keeps its refusal): only when numpy would use std::sort inside x86-simd-sort.
pub fn np_default_argsort_i64(v: &[i64], out: &mut [usize]) -> bool {
    match np_path() {
        NpPath::Avx512 => xss_argsort::<8, true, i64>(v, out),
        NpPath::Avx2 => xss_argsort::<4, false, i64>(v, out),
        NpPath::Intro => {
            intro_argsort::<i64>(v, out);
            true
        }
    }
}
pub fn np_default_argsort_i32(v: &[i32], out: &mut [usize]) -> bool {
    match np_path() {
        NpPath::Avx512 => xss_argsort::<8, true, i32>(v, out),
        NpPath::Avx2 => xss_argsort::<4, false, i32>(v, out),
        NpPath::Intro => {
            intro_argsort::<i32>(v, out);
            true
        }
    }
}
pub fn np_default_argsort_f64(v: &[f64], out: &mut [usize]) -> bool {
    match np_path() {
        NpPath::Avx512 | NpPath::Avx2 => {
            if f64::any_nan(v) {
                false
            } else if np_path() == NpPath::Avx512 {
                xss_argsort::<8, true, f64>(v, out)
            } else {
                xss_argsort::<4, false, f64>(v, out)
            }
        }
        NpPath::Intro => {
            intro_argsort::<f64>(v, out);
            true
        }
    }
}
pub fn np_default_argsort_f32(v: &[f32], out: &mut [usize]) -> bool {
    match np_path() {
        NpPath::Avx512 | NpPath::Avx2 => {
            if f32::any_nan(v) {
                false
            } else if np_path() == NpPath::Avx512 {
                xss_argsort::<8, true, f32>(v, out)
            } else {
                xss_argsort::<4, false, f32>(v, out)
            }
        }
        NpPath::Intro => {
            intro_argsort::<f32>(v, out);
            true
        }
    }
}

