template <typename T>
bool less_nanlast(T a, T b) { return a < b; }
template <>
bool less_nanlast<double>(double a, double b) { return a < b || (b != b && a == a); }
template <>
bool less_nanlast<float>(float a, float b) { return a < b || (b != b && a == a); }

static int msb_int(int64_t n) {
    int r = 0;
    while (n > 1) { n >>= 1; r++; }
    return r;
}

template <typename T>
void aheapsort(const T *v, int64_t *tosort, int64_t n) {
    int64_t *a = tosort - 1;
    int64_t i, j, l, tmp;
    for (l = n >> 1; l > 0; --l) {
        tmp = a[l];
        for (i = l, j = l << 1; j <= n;) {
            if (j < n && less_nanlast(v[a[j]], v[a[j + 1]])) ++j;
            if (less_nanlast(v[tmp], v[a[j]])) {
                a[i] = a[j];
                i = j;
                j += j;
            } else break;
        }
        a[i] = tmp;
    }
    for (; n > 1;) {
        tmp = a[n];
        a[n] = a[1];
        n -= 1;
        for (i = 1, j = 2; j <= n;) {
            if (j < n && less_nanlast(v[a[j]], v[a[j + 1]])) ++j;
            if (less_nanlast(v[tmp], v[a[j]])) {
                a[i] = a[j];
                i = j;
                j += j;
            } else break;
        }
        a[i] = tmp;
    }
}

template <typename T>
void aquicksort(T *v, int64_t *tosort, int64_t num) {
    int64_t *pl = tosort;
    int64_t *pr = tosort + num - 1;
    int64_t *stack[130];
    int64_t **sptr = stack;
    int64_t *pm, *pi, *pj, *pk, vi;
    int depth[130];
    int *psdepth = depth;
    int cdepth = msb_int(num) * 2;
    for (;;) {
        if (cdepth < 0) {
            aheapsort(v, pl, pr - pl + 1);
            goto stack_pop;
        }
        while ((pr - pl) > 15) {
            pm = pl + ((pr - pl) >> 1);
            if (less_nanlast(v[*pm], v[*pl])) swap(*pm, *pl);
            if (less_nanlast(v[*pr], v[*pm])) swap(*pr, *pm);
            if (less_nanlast(v[*pm], v[*pl])) swap(*pm, *pl);
            T vp = v[*pm];
            pi = pl;
            pj = pr - 1;
            swap(*pm, *pj);
            for (;;) {
                do { ++pi; } while (less_nanlast(v[*pi], vp));
                do { --pj; } while (less_nanlast(vp, v[*pj]));
                if (pi >= pj) break;
                swap(*pi, *pj);
            }
            pk = pr - 1;
            swap(*pi, *pk);
            if (pi - pl < pr - pi) {
                *sptr++ = pi + 1;
                *sptr++ = pr;
                pr = pi - 1;
            } else {
                *sptr++ = pl;
                *sptr++ = pi - 1;
                pl = pi + 1;
            }
            *psdepth++ = --cdepth;
        }
        for (pi = pl + 1; pi <= pr; ++pi) {
            vi = *pi;
            T vp = v[vi];
            pj = pi;
            pk = pi - 1;
            while (pj > pl && less_nanlast(vp, v[*pk])) {
                *pj-- = *pk--;
            }
            *pj = vi;
        }
    stack_pop:
        if (sptr == stack) break;
        pr = *(--sptr);
        pl = *(--sptr);
        cdepth = *(--psdepth);
    }
}

